<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); ?>
<section class="portal-page-heading"><p class="eyebrow"><?= $e($match['phase_name']) ?> · <?= $e($match['group_name']) ?> · rodada <?= (int) $match['round_number'] ?></p><h1><?= $e($match['home_team_name']) ?> × <?= $e($match['away_team_name']) ?></h1><p><?= $e($match['match_date'] ?: 'Data a definir') ?> <?= $e(substr((string) ($match['match_time'] ?: ''), 0, 5)) ?> · <?= $e($match['venue_name'] ?: 'Local a definir') ?></p></section><section class="portal-score"><div><?= $e($match['home_team_name']) ?></div><strong><?= (int) $match['score']['home'] ?> × <?= (int) $match['score']['away'] ?></strong><div><?= $e($match['away_team_name']) ?></div></section><?php if ($match['events']): ?><section><h2>Registros da partida</h2><div class="event-list"><?php foreach ($match['events'] as $event): ?><div><span><?= $e($event['minute'] !== null ? $event['minute'] . "'" : '-') ?></span><strong><?= $e($event['athlete_name'] ? ($event['sporting_name'] ?: $event['athlete_name']) : $event['event_type']) ?></strong><small><?= $e($event['event_type']) ?> · <?= $e($event['team_name'] ?: '') ?></small></div><?php endforeach; ?></div></section><?php endif; ?><?php if ($match['lineups']): ?><section><h2>Escalacoes confirmadas</h2><div class="portal-grid"><div><h3><?= $e($match['home_team_name']) ?></h3><?php foreach ($match['lineups'] as $player): if ((int) $player['team_id'] === (int) $match['home_team_id']): ?><p><?= $e($player['shirt_number'] ?: '-') ?> · <?= $e($player['sporting_name'] ?: $player['athlete_name']) ?> <small><?= $e($player['role']) ?></small></p><?php endif; endforeach; ?></div><div><h3><?= $e($match['away_team_name']) ?></h3><?php foreach ($match['lineups'] as $player): if ((int) $player['team_id'] === (int) $match['away_team_id']): ?><p><?= $e($player['shirt_number'] ?: '-') ?> · <?= $e($player['sporting_name'] ?: $player['athlete_name']) ?> <small><?= $e($player['role']) ?></small></p><?php endif; endforeach; ?></div></div></section><?php endif; ?><?php if ($match['officials']): ?><section><h2>Arbitragem</h2><?php foreach ($match['officials'] as $official): ?><span class="official-pill"><?= $e($official['role']) ?>: <?= $e($official['display_name']) ?></span><?php endforeach; ?></section><?php endif; ?><p><a href="<?= $e($base . '/resultados') ?>">Voltar para resultados</a></p>
